  navGrid: 'Eigene Gitterlinien', gridSub: 'Wählen, welche Linien das 3x3- und das 4x4-Gitter der Kamera zeigen', grid3: '3x3 Gitter', grid4: '4x4 Gitter', gridHorizontal: 'Waagerecht', gridVertical: 'Senkrecht', gridDiagonals: 'Diagonalen',
